package team.ylab.gateway.security;

import org.springframework.core.annotation.Order;
import org.springframework.security.web.server.csrf.CsrfToken;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import org.springframework.web.server.WebFilter;
import org.springframework.web.server.WebFilterChain;
import reactor.core.publisher.Mono;

/**
 * Reactive WebFilter that subscribes to the deferred {@link CsrfToken} generated by Spring
 * Security.
 *
 * <p>Spring Security defers loading and writing the CSRF token to the repository until the {@code
 * Mono<CsrfToken>} exchange attribute is subscribed to. By subscribing here (with order {@code
 * -50}, running immediately after Spring Security's filter chain at {@code -100}), this filter
 * ensures the {@code XSRF-TOKEN} cookie is populated on safe requests (such as {@code GET
 * /api/v1/session} or web page navigation) so the Next.js SPA has access to it.
 */
@Component
@Order(-50)
public class CsrfCookieWebFilter implements WebFilter {

  @Override
  public Mono<Void> filter(ServerWebExchange exchange, WebFilterChain chain) {
    Mono<CsrfToken> csrfToken =
        exchange.getAttributeOrDefault(CsrfToken.class.getName(), Mono.empty());
    return csrfToken
        .doOnSuccess(
            token -> {
              // Subscribing triggers CookieServerCsrfTokenRepository.saveToken
            })
        .then(chain.filter(exchange));
  }
}
